"""Regression checks for the root updater generated by install.sh."""
import re
import subprocess
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
INSTALL = (ROOT / "install.sh").read_text()


def updater_source():
    match = re.search(r"cat > /usr/local/sbin/lanpulse-update\.new <<UPD\n(.*?)\nUPD\n", INSTALL, re.S)
    if not match:
        raise AssertionError("Could not locate the generated LanPulse updater")
    return match.group(1)


class UpdaterRollbackSafety(unittest.TestCase):
    def test_updater_verifies_staged_zip_checksum_before_unpacking(self):
        source = updater_source()
        checksum = source.index('sha256sum -c incoming.zip.sha256')
        unpack = source.index('unzip -q "\\$D/incoming.zip"')
        self.assertLess(checksum, unpack)
        self.assertIn('incoming.zip.sha256', source)
        self.assertIn('failed SHA-256 verification', source)

    def test_rollback_archive_is_verified_before_installing(self):
        source = updater_source()
        archive_create = source.index('tar -czf "\\$PREVIOUS_TMP"')
        archive_readback = source.index('tar -tzf "\\$PREVIOUS_TMP"')
        app_entry_check = source.index("opt/lanpulse/app.py")
        publish_archive = source.index('mv -f "\\$PREVIOUS_TMP" "\\$D/previous.tgz"')
        install_update = source.index('unzip -q "\\$D/incoming.zip"')
        self.assertLess(archive_create, archive_readback)
        self.assertLess(archive_readback, app_entry_check)
        self.assertLess(app_entry_check, publish_archive)
        self.assertLess(publish_archive, install_update)

    def test_failed_rollback_archive_stops_before_any_update_unpack(self):
        source = updater_source()
        failure = source.index("Could not create and verify the rollback archive")
        stop = source.index("exit 1", failure)
        unpack = source.index('unzip -q "\\$D/incoming.zip"')
        self.assertLess(failure, stop)
        self.assertLess(stop, unpack)
        self.assertIn('rm -f "\\$PREVIOUS_TMP"', source[:failure])

    def test_rollback_archive_includes_python_environment_and_service_configuration(self):
        source = updater_source()
        archive_command = source[source.index("tar -czf"):source.index("then", source.index("tar -czf"))]
        self.assertIn("--exclude=opt/lanpulse/data", archive_command)
        self.assertNotIn("--exclude=opt/lanpulse/venv", archive_command)
        self.assertIn("opt/lanpulse etc/default/lanpulse", archive_command)
        self.assertIn("etc/systemd/system/lanpulse.service", archive_command)
        self.assertIn("etc/systemd/system/lanpulse.service.d", archive_command)
        self.assertIn("grep '^opt/lanpulse/venv/' >/dev/null", archive_command)
        self.assertIn("grep -x 'etc/default/lanpulse' >/dev/null", archive_command)
        self.assertIn("grep -x 'etc/systemd/system/lanpulse.service' >/dev/null", archive_command)
        self.assertIn("grep -x 'etc/systemd/system/lanpulse.service.d/hardening.conf' >/dev/null", archive_command)

    def test_rollback_reloads_restored_systemd_configuration(self):
        source = updater_source()
        restore = source.index('tar -xzf "\\$D/previous.tgz"')
        reload = source.index("systemctl daemon-reload", restore)
        restart = source.index("systemctl restart lanpulse", reload)
        self.assertLess(restore, reload)
        self.assertLess(reload, restart)

    def test_previous_archive_is_not_written_directly(self):
        source = updater_source()
        self.assertNotIn('tar -czf "\\$D/previous.tgz"', source)
        self.assertIn('PREVIOUS_TMP="\\$D/previous.tgz.tmp.\\$\\$"', source)


    def test_generated_updater_passes_bash_syntax_check(self):
        source = updater_source().replace(r"\$", "$").replace("$DEST", "/opt/lanpulse")
        result = subprocess.run(
            ["bash", "-n"],
            input=source,
            text=True,
            capture_output=True,
            check=False,
        )
        self.assertEqual(result.returncode, 0, result.stderr)

    def test_upload_staging_writes_sha256_sidecar_and_apply_requires_it(self):
        app = (ROOT / "app.py").read_text()
        self.assertIn('incoming.zip.sha256.tmp', app)
        self.assertIn('staged update is missing or failed SHA-256 verification', app)
        self.assertIn('hashlib.sha256()', app)

    def test_installer_checks_generated_updater_before_replacing_it(self):
        syntax_check = INSTALL.index("bash -n /usr/local/sbin/lanpulse-update.new")
        replace_updater = INSTALL.index(
            "mv -f /usr/local/sbin/lanpulse-update.new /usr/local/sbin/lanpulse-update"
        )
        self.assertLess(syntax_check, replace_updater)

    def test_systemd_backup_directory_is_configured_and_writable(self):
        hardening = INSTALL.split("cat > /etc/systemd/system/lanpulse.service.d/hardening.conf <<HARDEN", 1)[1]
        hardening = hardening.split("\\nHARDEN", 1)[0]
        self.assertIn("Environment=LANPULSE_BACKUP_DIR=/var/backups/lanpulse", hardening)
        self.assertIn("ReadWritePaths=$DEST/data /var/backups/lanpulse", hardening)

    def test_update_failure_verifies_rollback_files_and_service(self):
        source = updater_source()
        self.assertIn(
            ') >> "\\$LOG" 2>&1 && systemctl is-active --quiet lanpulse; then',
            source,
        )
        restore = source.index(r'tar -xzf "\$D/previous.tgz"')
        compare = source.index(r'tar -dzf "\$D/previous.tgz"', restore)
        reload = source.index("systemctl daemon-reload", compare)
        restart = source.index("systemctl restart lanpulse", reload)
        active = source.index("systemctl is-active --quiet lanpulse", restart)
        self.assertLess(restore, compare)
        self.assertLess(compare, reload)
        self.assertLess(reload, restart)
        self.assertLess(restart, active)
        self.assertIn("The previous version was restored and verified", source)
        self.assertIn("automatic rollback could not be verified", source)

    def test_update_log_is_reset_once_at_the_start_of_a_run(self):
        source = updater_source()
        reset = source.index('echo "== LanPulse update \\$(date) ==" > "\\$LOG"')
        self.assertLess(reset, source.index('sha256sum -c incoming.zip.sha256'))
        # Everything after the reset appends, so earlier progress lines are never wiped mid-run.
        self.assertEqual(len(re.findall(r'(?<!>)> "\\\$LOG"', source)), 1)

    def test_installer_never_disables_hardening_after_start_failure(self):
        startup = INSTALL.split("systemctl enable lanpulse.service", 1)[1]
        startup = startup.split("# ---- in-dashboard updates", 1)[0]
        self.assertIn("if ! systemctl restart lanpulse.service; then", startup)
        self.assertIn("The hardening configuration has been preserved.", startup)
        self.assertIn("exit 1", startup)
        self.assertNotIn("hardening.conf.off", INSTALL)
        self.assertNotIn("mv /etc/systemd/system/lanpulse.service.d/hardening.conf", startup)


if __name__ == "__main__":
    unittest.main()
